const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (input) => {
    let count4 = 0;
    let count7 = 0;

    if (input.includes('4') || input.includes('7')) {
        for (let i = 0; i < input.length; i++) {
            if (input[i] === '4') {
                count4++;
